import type { VariableConfig } from '../../Variable';
import type { Record } from '../../../db/Record';
/**
 * Configuration type for wide single line text variables
 */
export type WideSingleLineTextVariableType<Type extends string = string> = VariableConfig<Type> & {
    /** Whether to validate the regex expression pattern */
    validateRegex?: string | Record<'question_regex'>;
};
/**
 * A Variable for a wide single line text field.
 *
 * @see https://docs.servicenow.com/csh?topicname=variable-types.html&version=latest
 *
 * @param config - Configuration for the wide single line text variable including:
 *   * **question** - Question text displayed to the user
 *   * **validateRegex**? - Whether to validate the regex expression pattern
 *   * **defaultValue**? - Default value for the variable
 *   * And all other properties from the base Variable type
 */
export declare function WideSingleLineTextVariable(config: WideSingleLineTextVariableType): WideSingleLineTextVariableType<string>;
